insert into packages (id, duration_nights, price_from, currency, operated_by_provider_id, price_type) select (select id from nodes where node_type = 'package' and slug = '7-night-maldives-fly-fishing-holiday-half-day'), 7, 1443, 'USD', p.operated_by_provider_id, 'per-person' from packages p where p.id = (select id from nodes where node_type = 'package' and slug = '5-night-maldives-fly-fishing-holiday') on conflict (id) do nothing;
insert into bookable_products (id, booking_mode, base_price, currency) select (select id from nodes where node_type = 'package' and slug = '7-night-maldives-fly-fishing-holiday-half-day'), 'inquiry', 1443, 'USD' on conflict (id) do nothing;
insert into node_categories (node_id, category_id) select (select id from nodes where node_type = 'package' and slug = '7-night-maldives-fly-fishing-holiday-half-day'), category_id from node_categories where node_id = (select id from nodes where node_type = 'package' and slug = '5-night-maldives-fly-fishing-holiday') on conflict (node_id, category_id) do nothing;
insert into node_locations (node_id, location_id, relation) select (select id from nodes where node_type = 'package' and slug = '7-night-maldives-fly-fishing-holiday-half-day'), location_id, relation from node_locations where node_id = (select id from nodes where node_type = 'package' and slug = '5-night-maldives-fly-fishing-holiday') on conflict (node_id, location_id) do nothing;
insert into package_itinerary_stages (package_id, stage_number, day_start, day_end, night_count, title, description, sort_order) values ((select id from nodes where node_type = 'package' and slug = '7-night-maldives-fly-fishing-holiday-half-day'), 1, 1, 7, 7, 'Maldives Fishing and Holidays Lodge', '7 nights at Maldives Fishing and Holidays Lodge, Maamendhoo, Gaafu Alifu Atoll, with 6 days of half-day fly fishing on a private boat for your group. Full-board meals, twin-share rooms, airport meet and greet, return domestic flight and boat transfer included.', 1) on conflict (package_id, stage_number) do nothing;
insert into package_itinerary_stages (package_id, stage_number, day_start, day_end, night_count, title, description, sort_order) values ((select id from nodes where node_type = 'package' and slug = '7-night-maldives-fly-fishing-holiday-half-day'), 2, 8, 8, 0, 'Departure', 'Boat transfer to the domestic airport and return domestic flight to Velana International Airport, timed around the guest''s international flight.', 2) on conflict (package_id, stage_number) do nothing;
insert into package_itinerary_items (stage_id, component_type, component_node_id, component_role, quantity, sort_order) select s.id, 'node', (select id from nodes where node_type = 'accommodation' and slug = 'maldives-fishing-and-holidays-lodge'), 'accommodation', 1, 0 from package_itinerary_stages s where s.package_id = (select id from nodes where node_type = 'package' and slug = '7-night-maldives-fly-fishing-holiday-half-day') and s.stage_number = 1 and not exists (select 1 from package_itinerary_items i where i.stage_id = s.id);
insert into package_itinerary_items (stage_id, component_type, component_node_id, component_role, quantity, notes, sort_order) select s.id, 'node', (select id from nodes where node_type = 'activity' and slug = 'fly-fishing-half-day-charter'), 'activity', 6, '6 days of half-day fly fishing on the flats and reef edges.', 1 from package_itinerary_stages s where s.package_id = (select id from nodes where node_type = 'package' and slug = '7-night-maldives-fly-fishing-holiday-half-day') and s.stage_number = 1 and not exists (select 1 from package_itinerary_items i where i.stage_id = s.id and i.component_role = 'activity');
